class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        nonzero = [x for x in nums if x != 0]
        has_zero = len(nonzero) < len(nums)

        if not nonzero:
            return 0

        if len(nonzero) == 1 and nonzero[0] < 0:
            return 0 if has_zero else nonzero[0]

        negs = sorted([x for x in nonzero if x < 0], key=lambda v: abs(v))
        pos = [x for x in nonzero if x > 0]

        if len(negs) % 2 == 1:
            # drop the negative with smallest absolute value
            negs = negs[1:]

        product = 1
        for x in pos + negs:
            product *= x

        if not pos and not negs:
            return 0
        return product

